  axis_pins.name = 'axis_pins';
  meridian_arch.add(axis_pins);

  const pinGeometry = new THREE.CylinderGeometry(pinRadius, pinRadius, pinLength, 16);
  const pinPositionRadius = globeRadius + (pinLength / 2);

